fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Ensure both vectors have the same length
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    
    // Use iterators to perform element-wise bitwise AND
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x & y)
        .collect()
}